import React from 'react';
import Slider from "react-slick"; // Make sure to install react-slick and slick-carousel

// Import slick-carousel styles
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

function EventsSlider() {
  // Sağ ve Sol ok tuşları bileşeni
  const ArrowButton = ({ direction, onClick }) => {
    return (
      <div
        onClick={onClick}
        style={{
          position: "absolute",
          top: "50%",
          [direction]: "-50px", // Okları slider dışında pozisyonla
          transform: "translateY(-50%)",
          backgroundColor: "#FFFF",
          borderRadius: "50%",
          width: "40px",
          height: "40px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          cursor: "pointer",
          zIndex: 10,
        }}
      >
        <span style={{ color: "#00b666", fontSize: "20px" }}>
          {direction === "left" ? "<" : ">"}
        </span>
      </div>
    );
  };
  

  const settings = {
    dots: true,
    arrows: true,
    infinite: true,
    autoplay: true,
    autoplaySpeed: 51000,
    slidesToShow: 1,
    slidesToScroll: 1,
    nextArrow: <ArrowButton direction="right" />, // Sağ yön ok
    prevArrow: <ArrowButton direction="left" />,  // Sol yön ok
  };

  return (
    <div style={styles.wrapper}>
      {/* Ana İçerik */}
      <div style={styles.content}>
        {/* Slider Component */}
        <Slider {...settings} style={styles.slider}>
          <div style={styles.contentBox}>
            {/* Tek bir görsel gösterilecek */}
            <img
              src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2F1112_412_2_cd52574011%2F1112_412_2_cd52574011.png&w=1200&q=100"
              alt="Slide 1"
              style={styles.image}
            />
          </div>
          <div style={styles.contentBox}>
            <img
              src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2F1112_412_2_cd52574011%2F1112_412_2_cd52574011.png&w=1200&q=100"
              alt="Slide 2"
              style={styles.image}
            />
          </div>
          <div style={styles.contentBox}>
            <img
              src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2F1112_412_2_cd52574011%2F1112_412_2_cd52574011.png&w=1200&q=100"
              alt="Slide 3"
              style={styles.image}
            />
          </div>
        </Slider>
      </div>

      {/* Alt Mavi Bar */}
      <div style={styles.bottomBar}></div>
    </div>
  );
}

const styles = {
  wrapper: {
    position: "relative",
    width: "100vw", // Tarayıcının tam genişliği
    margin: "0 auto",
    backgroundColor: "rgb(246, 248, 255)",
    overflow: "hidden",
  },
  
  content: {
    display: "flex",
    justifyContent: "center", // Ortala
    alignItems: "center", // Dikey hizala
    width: "100%",
    margin: "0",
  },
  

  slider: {
    width: "80%", // Slider genişliğini %80 ile sınırladım
    margin: "0 auto", // Slider'ı ortaladım
    height: "auto", // İçeriğe göre otomatik yükseklik
    overflow: "visible", // Gölge taşmasını sağlar
  },

  contentBox: {
    width: "100%",
    height: "400px",
    margin: "0", // Kenar boşluklarını sıfırla
    padding: "0", // İç boşlukları sıfırla
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  },
  

  image: {
    width: "auto", // Görselin genişliği
    maxHeight: "100%", // Görselin yüksekliği kutu boyutunu aşamaz
    objectFit: "contain", // Görsel boyutunu koruyarak sığdırır
    borderRadius: "5px",
    boxShadow: "0 4px 8px rgba(0, 0, 0, 0.2)", // Shadow
  },

  bottomBar: {
    width: "100%", // Tam genişlik
    height: "100px",
    backgroundColor: "#293349",
    marginTop: "5px",
  },
};


export default EventsSlider;
